}

function parseInteger(value) {
  if (!isIntegerLiteral(value)) {
    return null;
  }

  return Number.parseInt(value, 10);
}

function canConsumeIntValue(value) {
  return value !== undefined && (value === '-' || !value.startsWith('-') || isNegativeIntegerToken(value));
}

function canConsumeStringValue(value) {
  return value !== undefined && (value === '-' || !value.startsWith('-'));
}

export function parseTest3Args(argv, progName) {
  let a;
  let b;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
