      break;
    }

    if (token.startsWith('--a=')) {
      const rawValue = token.slice(4);
      const parsedValue = parseInteger(rawValue);

      if (parsedValue === null) {
        return {
          kind: 'error',
          text: buildArgumentError(progName, `argument --a: invalid int value: '${rawValue}'`),
        };
      }

      a = parsedValue;
      continue;
    }

    if (token === '--a') {
      const rawValue = argv[index + 1];

      if (!canConsumeIntValue(rawValue)) {
        return {
          kind: 'error',
          text: buildArgumentError(progName, 'argument --a: expected one argument'),
        };
      }

      index += 1;
      const parsedValue = parseInteger(rawValue);

      if (parsedValue === null) {
        return {
          kind: 'error',
          text: buildArgumentError(progName, `argument --a: invalid int value: '${rawValue}'`),
        };
      }

      a = parsedValue;
      continue;
    }

    if (token.startsWith('--b=')) {
      b = token.slice(4);
      continue;
    }

    if (token === '--b') {
      const rawValue = argv[index + 1];

      if (!canConsumeStringValue(rawValue)) {
        return {
          kind: 'error',
          text: buildArgumentError(progName, 'argument --b: expected one argument'),
        };
      }

      index += 1;
      b = rawValue;
      continue;
